<template>
  <PageContainer title="自动策略" description="真实行情与风控规则驱动的策略执行，订单仍在模拟账户内成交">
    <template #actions>
      <el-select v-if="accounts.length" v-model="accountId" placeholder="选择自动交易账户" class="account-select" @change="loadWorkspace"><el-option v-for="item in accounts" :key="item.id" :label="item.name" :value="item.id" /></el-select>
