    <el-alert title="仅执行模拟交易。影子策略必须通过真实历史回测并经人工检查后才能晋级；真实盘口缺失、非交易时段或高风险时不会下单。" type="warning" show-icon :closable="false" class="notice" />

    <el-empty v-if="!accounts.length&&!loading" description="尚未创建自动交易账户"><el-button type="primary" @click="createVisible=true">开始配置</el-button></el-empty>
    <template v-else-if="current">
      <section class="status-band">
        <div><span>运行状态</span><el-tag :type="current.status==='ACTIVE'?'success':'info'">{{statusText(current.status)}}</el-tag></div>
        <div><span>关联模拟账户</span><strong>#{{current.paper_account_id}}</strong></div>
        <div><span>单票仓位上限</span><strong>{{percent(current.max_position_ratio)}}</strong></div>
        <div><span>组合总仓位上限</span><strong>{{percent(current.max_total_position_ratio)}}</strong></div>
        <div><span>最低信号分</span><strong>{{current.min_signal_score}}</strong></div>
        <div><span>最大持股数</span><strong>{{current.max_symbols}} 只</strong></div>
        <div class="status-actions"><el-button :loading="running" :disabled="!promoted||current.status==='ACTIVE'" type="primary" @click="start">启用自动交易</el-button><el-button :disabled="current.status!=='ACTIVE'" @click="pause">暂停</el-button><el-button :disabled="current.status!=='PAUSED'" @click="openEdit">编辑</el-button><el-button :disabled="current.status!=='PAUSED'" type="danger" plain @click="archiveCurrent">归档</el-button></div>
      </section>

      <el-tabs v-model="tab" class="workspace-tabs">
        <el-tab-pane label="策略版本" name="strategies">
          <div class="toolbar"><div><strong>策略版本</strong><span>新配置先进入影子阶段，检查参数和回测证据后再晋级</span></div><el-button type="primary" plain @click="generateVisible=true">生成策略草案</el-button></div>
          <div class="table-scroll-x"><el-table :data="strategies" v-loading="loading" min-width="1000" empty-text="尚未生成策略">
            <el-table-column prop="version_no" label="版本" width="80"><template #default="{row}">v{{row.version_no}}</template></el-table-column>
            <el-table-column prop="name" label="策略名称" min-width="170" />
            <el-table-column label="算法" width="130"><template #default="{row}">{{strategyText(row.base_strategy)}}</template></el-table-column>
            <el-table-column label="来源" width="110"><template #default="{row}"><el-tag :type="row.source==='AI'?'primary':'info'">{{row.source==='AI'?'AI 生成':'量化规则'}}</el-tag></template></el-table-column>
            <el-table-column label="生命周期" width="110"><template #default="{row}"><el-tag :type="lifecycleType(row.lifecycle)">{{lifecycleText(row.lifecycle)}}</el-tag></template></el-table-column>
            <el-table-column label="回测评估" width="120"><template #default="{row}"><el-tag v-if="row.evaluation" :type="row.evaluation.passed?'success':'danger'">{{row.evaluation.passed?'已通过':'未通过'}}</el-tag><el-tag v-else type="info">未评估</el-tag></template></el-table-column>
            <el-table-column prop="rationale" label="生成理由" min-width="280" show-overflow-tooltip />
            <el-table-column label="操作" width="260" fixed="right"><template #default="{row}"><el-button size="small" @click="showStrategy(row)">详情</el-button><el-button v-if="row.lifecycle==='SHADOW'" size="small" :loading="evaluatingId===row.id" @click="evaluate(row.id)">真实回测</el-button><el-popconfirm v-if="row.lifecycle==='SHADOW'&&row.evaluation?.passed" title="确认已检查参数和回测证据，并将该版本晋级为执行策略？" @confirm="promote(row.id)"><template #reference><el-button size="small" type="primary">晋级</el-button></template></el-popconfirm></template></el-table-column>
          </el-table></div>
        </el-tab-pane>
        <el-tab-pane label="运行记录" name="runs">
          <div class="table-scroll-x"><el-table :data="runs" min-width="900" empty-text="尚无运行记录"><el-table-column prop="id" label="运行 ID" width="100"/><el-table-column label="状态" width="110"><template #default="{row}">{{runStatusText(row.status)}}</template></el-table-column><el-table-column prop="universe_size" label="候选范围" width="110"/><el-table-column prop="evaluated_count" label="已分析" width="100"/><el-table-column prop="order_count" label="模拟委托" width="100"/><el-table-column prop="started_at" label="开始时间" width="175"/><el-table-column prop="finished_at" label="完成时间" width="175"/><el-table-column prop="error_message" label="错误" min-width="220" show-overflow-tooltip/></el-table></div>
        </el-tab-pane>
        <el-tab-pane label="决策审计" name="decisions">
          <div class="table-scroll-x"><el-table :data="decisions" min-width="1180" empty-text="尚无策略决策"><el-table-column prop="created_at" label="时间" width="175"/><el-table-column label="股票" width="120"><template #default="{row}"><el-link @click="router.push(`/market/stocks/${row.symbol}`)">{{row.symbol}}</el-link></template></el-table-column><el-table-column label="信号" width="90"><template #default="{row}">{{signalText(row.signal)}}</template></el-table-column><el-table-column prop="score" label="信号分" width="90"/><el-table-column label="执行结果" width="130"><template #default="{row}">{{actionText(row.action)}}</template></el-table-column><el-table-column prop="risk_result" label="风险" width="100"/><el-table-column prop="quantity" label="数量" width="100"/><el-table-column prop="limit_price" label="盘口限价" width="110"/><el-table-column prop="reason" label="决策依据" min-width="320" show-overflow-tooltip/><el-table-column label="详情" width="90" fixed="right"><template #default="{row}"><el-button size="small" @click="showDecision(row)">查看</el-button></template></el-table-column></el-table></div>
        </el-tab-pane>
        <el-tab-pane label="交割单" name="deliveries">
          <div class="toolbar"><div><strong>自动交易交割单</strong><span>仅展示策略决策触发并由五档盘口撮合形成的真实模拟成交</span></div><el-button :disabled="!deliveries.length" @click="exportDeliveries">导出 CSV</el-button></div>
          <div class="table-scroll-x"><el-table :data="deliveries" min-width="1480" empty-text="尚无自动交易成交记录">
            <el-table-column prop="trade_time" label="成交时间" width="175" />
            <el-table-column prop="trade_no" label="成交编号" width="190" show-overflow-tooltip />
            <el-table-column label="股票" width="150"><template #default="{row}"><el-link @click="router.push(`/market/timeshare/${row.symbol}`)">{{row.name||row.symbol}} {{row.symbol}}</el-link></template></el-table-column>
            <el-table-column label="方向" width="80"><template #default="{row}"><span :class="row.side==='BUY'?'rise-text':'fall-text'">{{row.side==='BUY'?'买入':'卖出'}}</span></template></el-table-column>
            <el-table-column label="委托类型" width="90"><template #default="{row}">{{row.order_type==='LIMIT'?'限价':'市价'}}</template></el-table-column>
            <el-table-column prop="order_price" label="委托价" width="100" />
            <el-table-column prop="fill_price" label="成交价" width="100" />
            <el-table-column prop="quantity" label="成交数量" width="100" />
            <el-table-column prop="amount" label="成交金额" width="120"><template #default="{row}">{{money(row.amount)}}</template></el-table-column>
            <el-table-column label="费用" width="110"><template #default="{row}">{{money(Number(row.fee||0)+Number(row.stamp_duty||0))}}</template></el-table-column>
            <el-table-column label="策略版本" width="150"><template #default="{row}">v{{row.strategy_version}} {{row.strategy_name}}</template></el-table-column>
            <el-table-column prop="decision_reason" label="决策依据" min-width="300" show-overflow-tooltip />
            <el-table-column prop="quote_time" label="盘口时间" width="175" />
            <el-table-column label="数据" width="90"><template #default="{row}"><el-tag :type="String(row.data_mode).toLowerCase()==='real'?'success':'danger'">{{String(row.data_mode).toLowerCase()==='real'?'真实':'异常'}}</el-tag></template></el-table-column>
          </el-table></div>
        </el-tab-pane>
      </el-tabs>
    </template>

    <el-dialog v-model="createVisible" title="新建自动交易账户" width="min(620px,94vw)"><el-form label-position="top"><el-form-item label="账户名称"><el-input v-model="createForm.name" placeholder="例如：趋势策略模拟组合"/></el-form-item><el-form-item label="关联模拟账户"><el-select v-model="createForm.paper_account_id" placeholder="先选择一个模拟账户" style="width:100%"><el-option v-for="item in paperAccounts" :key="item.id" :label="`${item.account_name}（可用资金 ${item.cash}）`" :value="item.id"/></el-select></el-form-item><div class="form-flex"><el-form-item label="单票仓位上限"><el-input-number v-model="createForm.max_position_ratio" :min="0.01" :max="0.3" :step="0.01"/><small>例如 0.10 表示一只股票最多占总资产 10%</small></el-form-item><el-form-item label="组合总仓位上限"><el-input-number v-model="createForm.max_total_position_ratio" :min="0.1" :max="1" :step="0.05"/><small>所有持仓合计不得超过总资产的该比例</small></el-form-item><el-form-item label="每日最大亏损"><el-input-number v-model="createForm.max_daily_loss_ratio" :min="0.005" :max="0.1" :step="0.005"/><small>以当日首次运行资产为基准，触达后停止新增委托</small></el-form-item><el-form-item label="最低信号分"><el-input-number v-model="createForm.min_signal_score" :min="50" :max="100"/><small>低于该分数只记录，不执行</small></el-form-item><el-form-item label="最大持股数"><el-input-number v-model="createForm.max_symbols" :min="1" :max="50"/><small>候选扫描不受此项限制，仅约束持仓</small></el-form-item></div></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="createAccount">创建</el-button></template></el-dialog>
    <el-dialog v-model="editVisible" title="编辑自动交易账户" width="min(620px,94vw)"><el-alert title="只有已暂停账户可以编辑。修改风控参数不会改写历史决策和成交。" type="info" :closable="false"/><el-form label-position="top" class="generate-form"><el-form-item label="账户名称"><el-input v-model="editForm.name"/></el-form-item><div class="form-flex"><el-form-item label="单票仓位上限"><el-input-number v-model="editForm.max_position_ratio" :min="0.01" :max="0.3" :step="0.01"/></el-form-item><el-form-item label="组合总仓位上限"><el-input-number v-model="editForm.max_total_position_ratio" :min="0.1" :max="1" :step="0.05"/></el-form-item><el-form-item label="每日最大亏损"><el-input-number v-model="editForm.max_daily_loss_ratio" :min="0.005" :max="0.1" :step="0.005"/></el-form-item><el-form-item label="最低信号分"><el-input-number v-model="editForm.min_signal_score" :min="50" :max="100"/></el-form-item><el-form-item label="最大持股数"><el-input-number v-model="editForm.max_symbols" :min="1" :max="50"/></el-form-item></div></el-form><template #footer><el-button @click="editVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEdit">保存</el-button></template></el-dialog>
    <el-dialog v-model="generateVisible" title="AI 生成受约束策略" width="min(660px,94vw)"><el-alert title="先选择接近的研究目标，再按自己的风险偏好修改。AI 只会选择白名单算法和参数。" type="info" show-icon :closable="false"/><el-form label-position="top" class="generate-form"><el-form-item label="AI 生成研究目标（必填）"><el-select placeholder="选择一个适合新手的目标模板" style="width:100%;margin-bottom:10px" @change="applyObjectiveTemplate"><el-option v-for="item in objectiveTemplates" :key="item.label" :label="item.label" :value="item.text"/></el-select><el-input v-model="objective" type="textarea" :rows="6" placeholder="例如：以控制回撤为首要目标，关注20至60个交易日趋势……"/><small>请写清关注周期、风险偏好、趋势或反转倾向。系统不会接受任意代码，也不会生成收益承诺。</small></el-form-item></el-form><template #footer><el-button @click="generateVisible=false">取消</el-button><el-button type="primary" :loading="generating" @click="generate">生成影子策略</el-button></template></el-dialog>
    <el-drawer v-model="detailVisible" :title="detailTitle" size="min(720px,94vw)"><template v-if="selectedStrategy"><el-descriptions :column="1" border><el-descriptions-item label="算法">{{strategyText(selectedStrategy.base_strategy)}}</el-descriptions-item><el-descriptions-item label="来源">{{selectedStrategy.source==='AI'?`${selectedStrategy.model_provider} / ${selectedStrategy.model_name}`:'量化规则'}}</el-descriptions-item><el-descriptions-item label="说明">{{selectedStrategy.rationale}}</el-descriptions-item><el-descriptions-item label="回测状态">{{selectedStrategy.evaluation?(selectedStrategy.evaluation.passed?'通过晋级门槛':'未通过晋级门槛'):'尚未评估'}}</el-descriptions-item></el-descriptions><template v-if="selectedStrategy.evaluation"><h3>真实历史回测摘要</h3><div class="evaluation-summary"><span>样本 {{selectedStrategy.evaluation.successful_symbols}}/{{selectedStrategy.evaluation.tested_symbols}}</span><span>交易 {{selectedStrategy.evaluation.total_trades}} 次</span><span>平均年化 {{percent(selectedStrategy.evaluation.annual_return)}}</span><span>最大回撤 {{percent(selectedStrategy.evaluation.max_drawdown)}}</span><span>胜率 {{percent(selectedStrategy.evaluation.win_rate)}}</span></div><pre>{{JSON.stringify(selectedStrategy.evaluation.evidence,null,2)}}</pre></template><h3>完整参数</h3><pre>{{JSON.stringify(selectedStrategy.config,null,2)}}</pre></template><template v-else-if="selectedDecision"><el-descriptions :column="1" border><el-descriptions-item label="执行结果">{{actionText(selectedDecision.action)}}</el-descriptions-item><el-descriptions-item label="决策依据">{{selectedDecision.reason}}</el-descriptions-item><el-descriptions-item label="关联模拟订单">{{selectedDecision.paper_order_id||'未下单'}}</el-descriptions-item><el-descriptions-item label="追踪编号">{{selectedDecision.trace_id}}</el-descriptions-item></el-descriptions><h3>真实数据证据</h3><pre>{{JSON.stringify(selectedDecision.evidence,null,2)}}</pre></template></el-drawer>
  </PageContainer>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageContainer from '@/components/common/PageContainer.vue'
import { autoTraderApi } from '@/api/auto-trader'
import { paperApi } from '@/api/paper'
import type { PaperAccount } from '@/types/paper'
import type { AutoDecision, AutoStrategy, AutoTradeAccount, AutoTradeRun, DeliveryStatement } from '@/types/auto-trader'

const router=useRouter(),loading=ref(false),saving=ref(false),generating=ref(false),running=ref(false),evaluatingId=ref(0),accounts=ref<AutoTradeAccount[]>([]),paperAccounts=ref<PaperAccount[]>([]),strategies=ref<AutoStrategy[]>([]),runs=ref<AutoTradeRun[]>([]),decisions=ref<AutoDecision[]>([]),deliveries=ref<DeliveryStatement[]>([]),accountId=ref(0),tab=ref('strategies'),createVisible=ref(false),editVisible=ref(false),generateVisible=ref(false),detailVisible=ref(false),selectedStrategy=ref<AutoStrategy>(),selectedDecision=ref<AutoDecision>(),objective=ref('控制回撤，结合趋势、动量和成交量确认，在 A 股 T+1 约束下进行模拟交易')
const createForm=reactive({name:'策略模拟组合',paper_account_id:0,max_position_ratio:0.1,max_total_position_ratio:0.8,max_daily_loss_ratio:0.02,min_signal_score:70,max_symbols:10})
const editForm=reactive({name:'',max_position_ratio:0.1,max_total_position_ratio:0.8,max_daily_loss_ratio:0.02,min_signal_score:70,max_symbols:10})
const objectiveTemplates=[{label:'低回撤趋势研究',text:'以控制最大回撤为首要目标，研究20至60个交易日的中短期趋势，使用均线、动量和成交量共同确认，减少频繁交易，并遵守A股T+1规则。'},{label:'量价突破研究',text:'研究成交量显著放大并突破近期压力位的股票，要求突破后趋势持续性较好，同时严格控制单票仓位和追高风险。'},{label:'均线趋势研究',text:'研究短期均线上穿中期均线后的趋势延续，结合MACD与成交量过滤弱信号，偏好较低换手和明确止损风险提示。'},{label:'超卖反弹研究',text:'研究RSI超卖后的技术性反弹，但必须结合趋势、支撑位和市场风险过滤，不在明显下跌趋势中盲目参与。'}]
const current=computed(()=>accounts.value.find(v=>v.id===accountId.value)),promoted=computed(()=>strategies.value.some(v=>v.lifecycle==='PROMOTED')),detailTitle=computed(()=>selectedStrategy.value?'策略版本详情':'决策证据详情')
const loadAccounts=async()=>{accounts.value=await autoTraderApi.accounts();paperAccounts.value=await paperApi.accounts();if(!accounts.value.some(v=>v.id===accountId.value))accountId.value=accounts.value[0]?.id||0;if(accountId.value)await loadWorkspace()}
const loadWorkspace=async()=>{if(!accountId.value)return;loading.value=true;try{[strategies.value,runs.value,decisions.value,deliveries.value]=await Promise.all([autoTraderApi.strategies(accountId.value),autoTraderApi.runs(accountId.value),autoTraderApi.decisions(accountId.value),autoTraderApi.deliveries(accountId.value)])}finally{loading.value=false}}
const createAccount=async()=>{if(!createForm.name.trim())return ElMessage.warning('请输入账户名称');if(!createForm.paper_account_id)return ElMessage.warning('请选择模拟账户');saving.value=true;try{const item=await autoTraderApi.createAccount({...createForm});ElMessage.success('自动交易账户已创建');createVisible.value=false;await loadAccounts();accountId.value=item.id;await loadWorkspace()}finally{saving.value=false}}
const generate=async()=>{if(!accountId.value)return;if(!objective.value.trim())return ElMessage.warning('请填写 AI 生成研究目标，或选择一个目标模板');generating.value=true;try{const result=await autoTraderApi.generateStrategy(accountId.value,objective.value);ElMessage.success(result.notice||'影子策略已生成');generateVisible.value=false;await loadWorkspace()}finally{generating.value=false}}
const applyObjectiveTemplate=(text:string)=>{objective.value=text}
const openEdit=()=>{if(!current.value)return;Object.assign(editForm,{name:current.value.name,max_position_ratio:current.value.max_position_ratio,max_total_position_ratio:current.value.max_total_position_ratio,max_daily_loss_ratio:current.value.max_daily_loss_ratio,min_signal_score:current.value.min_signal_score,max_symbols:current.value.max_symbols});editVisible.value=true}
const saveEdit=async()=>{if(!current.value)return;if(!editForm.name.trim())return ElMessage.warning('请输入账户名称');saving.value=true;try{await autoTraderApi.updateAccount(current.value.id,{...editForm});ElMessage.success('账户配置已保存');editVisible.value=false;await loadAccounts()}finally{saving.value=false}}
const archiveCurrent=async()=>{if(!current.value)return;await ElMessageBox.confirm('归档后账户不会继续运行，但历史策略、决策、订单、成交和交割单会保留。是否归档？','归档自动交易账户',{type:'warning',confirmButtonText:'确认归档',cancelButtonText:'取消'});await autoTraderApi.archiveAccount(current.value.id);ElMessage.success('账户已归档');await loadAccounts()}
const exportDeliveries=async()=>{if(!accountId.value)return;await autoTraderApi.exportDeliveries(accountId.value);ElMessage.success('交割单已导出')}
const evaluate=async(id:number)=>{evaluatingId.value=id;try{const result=await autoTraderApi.evaluate(id);ElMessage[result.evaluation?.passed?'success':'warning'](result.notice);await loadWorkspace()}finally{evaluatingId.value=0}}
const promote=async(id:number)=>{const result=await autoTraderApi.promote(id);ElMessage.success(result.notice||'策略已晋级');await loadWorkspace()}
const start=async()=>{if(!accountId.value)return;running.value=true;try{const result=await autoTraderApi.start(accountId.value);ElMessage.success(result.trading_session?'自动交易已启用，本轮分析与模拟执行已完成':'自动交易已启用；当前非交易时段，本轮分析已存档且未发送委托');await loadAccounts()}finally{running.value=false}}
